import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for LogSoftmax
log_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void log_softmax_kernel(const float* x, float* out, int size, int dim, int stride) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float max_val = -INFINITY;
        for (int i = 0; i < stride; ++i) {
            max_val = fmaxf(max_val, x[idx * stride + i]);
        }

        float sum_exp = 0.0f;
        for (int i = 0; i < stride; ++i) {
            sum_exp += expf(x[idx * stride + i] - max_val);
        }

        for (int i = 0; i < stride; ++i) {
            out[idx * stride + i] = x[idx * stride + i] - max_val - logf(sum_exp);
        }
    }
}

torch::Tensor log_softmax_cuda(torch::Tensor x, int dim) {
    auto size = x.numel() / x.size(dim);
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    log_softmax_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size, dim, x.size(dim));

    return out;
}
"""

log_softmax_cpp_source = (
    "torch::Tensor log_softmax_cuda(torch::Tensor x, int dim);"
)

# Compile the inline CUDA code for LogSoftmax
log_softmax = load_inline(
    name="log_softmax",
    cpp_sources=log_softmax_cpp_source,
    cuda_sources=log_softmax_source,
    functions=["log_softmax_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a LogSoftmax activation using a custom CUDA kernel.
    """
    def __init__(self, dim: int = 1):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.log_softmax = log_softmax

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies LogSoftmax activation to the input tensor using a custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, dim).

        Returns:
            torch.Tensor: Output tensor with LogSoftmax applied, same shape as input.
        """
        return self.log_softmax.log_softmax_cuda(x, self.dim)
